use std::fmt::Write;

use lazuli_ir::Resource;

/// Emit `e2e/_generated/lifecycle-gate.spec.ts`.
pub fn emit_playwright_lifecycle_gate(resources: &[Resource]) -> String {
    let mut s = String::new();

    writeln!(
        s,
        "// AUTO-GENERATED by `lazuli generate playwright --target=lifecycle-gate`. DO NOT EDIT."
    )
    .ok();
    writeln!(s, "import {{ test }} from '@playwright/test';").ok();
    writeln!(s).ok();

    for resource in resources
        .iter()
        .filter(|resource| resource.lifecycle.is_some())
    {
        let lifecycle = resource
            .lifecycle
            .as_ref()
            .expect("filtered to resources with lifecycle");

        writeln!(
            s,
            "test.describe('{} lifecycle', () => {{",
            escape_ts_single_quoted(&resource.name)
        )
        .ok();

        for transition in &lifecycle.transitions {
            writeln!(
                s,
                "  test.fixme('transition {} -> {}', async ({{ page, request }}) => {{",
                escape_ts_single_quoted(&transition.from.join(", ")),
                escape_ts_single_quoted(&transition.to)
            )
            .ok();
            writeln!(
                s,
                "    // TODO: fixtures pending plugin-scalar-fixtures-api. Fill payload"
            )
            .ok();
            writeln!(s, "    // when scalar-fixtures.gen.ts barrel is non-empty.").ok();
            writeln!(s, "  }});").ok();
        }

        writeln!(s, "}});").ok();
        writeln!(s).ok();
    }

    s
}

fn escape_ts_single_quoted(value: &str) -> String {
    let mut escaped = String::with_capacity(value.len());
    for ch in value.chars() {
        match ch {
            '\\' => escaped.push_str("\\\\"),
            '\'' => escaped.push_str("\\'"),
            '\n' => escaped.push_str("\\n"),
            '\r' => escaped.push_str("\\r"),
            '\t' => escaped.push_str("\\t"),
            _ => escaped.push(ch),
        }
    }
    escaped
}

#[cfg(test)]
mod tests {
    use lazuli_ir as ir;

    use super::emit_playwright_lifecycle_gate;

    #[test]
    fn emits_fixme_for_lifecycle_transition() {
        let resource = resource_with_lifecycle();
        let spec = emit_playwright_lifecycle_gate(&[resource]);

        assert!(spec.contains("test.describe('Order lifecycle', () => {"));
        assert!(spec.contains("test.fixme('transition draft -> submitted'"));
    }

    fn resource_with_lifecycle() -> ir::Resource {
        ir::Resource {
            name: "Order".to_owned(),
            public_contract: None,
            tenancy: None,
            soft_delete: false,
            timestamps: None,
            fields: Vec::new(),
            constraints: Vec::new(),
            validate: None,
            validates: Vec::new(),
            retention: None,
            previous_names: Vec::new(),
            span_ref: None,
            lifecycle: Some(ir::Lifecycle {
                discriminator_field: "status".to_owned(),
                generated_enum: "OrderStatus".to_owned(),
                states: vec![
                    lifecycle_state("draft", ir::LifecycleStateKind::Initial),
                    lifecycle_state("submitted", ir::LifecycleStateKind::Terminal),
                ],
                transitions: vec![ir::LifecycleTransition {
                    name: "submit".to_owned(),
                    from: vec!["draft".to_owned()],
                    to: "submitted".to_owned(),
                    policy: None,
                    audit: None,
                    timestamps: None,
                    emits: Vec::new(),
                    requires: None,
                    tests: None,
                    previous_names: Vec::new(),
                    span_ref: None,
                }],
                invariants: Vec::new(),
                invariant_handlers: Vec::new(),
                previous_names: Vec::new(),
                span_ref: None,
            }),
            invariants: Vec::new(),
            lock: None,
            composite_key: None,
            conventions: Vec::new(),
        }
    }

    fn lifecycle_state(name: &str, kind: ir::LifecycleStateKind) -> ir::LifecycleState {
        ir::LifecycleState {
            name: name.to_owned(),
            kind,
            span_ref: None,
        }
    }
}
